neo-brutalism.css:
/* ============================================
   ByteUI - Neo-Brutalism Theme Variables
   Add data-theme="neo" to any wrapper element
   ============================================ */

[data-theme="neo"] {
  --color-accent-1: #f76a9b;
  --shadow-lg-1: 10px 10px 0 #1e1e1e;
  --shadow-md-1: 6px 6px 0 #1e1e1e;

  --color-accent-2: #A8DADC;
  --shadow-lg-2: 10px 10px 0 #0c2d32;
  --shadow-md-2: 6px 6px 0 #0c2d32;

  --color-accent-3: #a0a0a0;
  --shadow-lg-3: 10px 10px 0 #1a1a1a;
  --shadow-md-3: 6px 6px 0 #1a1a1a;

  --color-accent-4: #F9C74F;
  --shadow-lg-4: 10px 10px 0 #222222;
  --shadow-md-4: 6px 6px 0 #222222;

  --color-accent-5: #5294ff;
  --shadow-lg-5: 10px 10px 0 #0a192f;
  --shadow-md-5: 6px 6px 0 #0a192f;

  --font-lexend: 'Lexend', sans-serif;
  --font-sans: 'Public Sans', sans-serif;
  --border-width: 3px;
  --border-width-thick: 4px;
  --border-radius: 15px;

  --warning: #F9C74F;
  --error: #E63946;
  --success: #2A9D8F;
  --default: #A8DADC;

  --color-bg: #F4F4F4;
  --color-surface: #FFFFFF;
  --color-text: #1c1c1e;
  --color-text-white: #ffffff;
  --color-text-black: #1c1c1e;
  --color-text-muted: #585757;
  --border-color: #000000;
}

/* Dark Mode overrides for Neo-Brutalism */
.dark [data-theme="neo"],
[data-theme="neo"].dark {
  --color-accent-1: #f76a9b;
  --shadow-lg-1: 10px 10px 0 #1e1e1e;
  --shadow-md-1: 6px 6px 0 #1e1e1e;

  --color-accent-2: #A8DADC;
  --shadow-lg-2: 10px 10px 0 #0c2d32;
  --shadow-md-2: 6px 6px 0 #0c2d32;

  --color-accent-3: #444444;
  --shadow-lg-3: 10px 10px 0 #1a1a1a;
  --shadow-md-3: 6px 6px 0 #1a1a1a;

  --color-accent-4: #F9C74F;
  --shadow-lg-4: 10px 10px 0 #222222;
  --shadow-md-4: 6px 6px 0 #222222;

  --color-accent-5: #5294ff;
  --shadow-lg-5: 10px 10px 0 #0a192f;
  --shadow-md-5: 6px 6px 0 #0a192f;

  --color-bg: #000000;
  --color-surface: #1a1a1a;
  --color-text: #ffffff;
  --color-text-white: #ffffff;
  --color-text-black: #000000;
  --color-text-muted: #A0A0A0;
  --border-color: #000000;
  --success: #2A9D8F;
  --warning: #F9C74F;
  --error: #E63946;
  --default: #b9f9f7;
}

code-block.content:
'use client'

import { useState } from 'react'
import { Copy, Check, ChevronDown, ChevronUp } from 'lucide-react'
import { motion } from 'framer-motion'
import SyntaxHighlighter from 'react-syntax-highlighter'
import { atomOneDark } from 'react-syntax-highlighter/dist/esm/styles/hljs'

export const CODE_BLOCK_COLLAPSED_HEIGHT = 'calc(24rem + 0.5rem)'

interface CodeBlockProps {
  code: string
  language?: string
  className?: string
  collapsible?: boolean
}

export function CodeBlock({
  code,
  language = 'typescript',
  className = '',
  collapsible = false,
}: CodeBlockProps) {
  const [copied, setCopied] = useState(false)
  const [expanded, setExpanded] = useState(false)

  const handleCopy = () => {
    navigator.clipboard.writeText(code)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  const isCollapsed = collapsible && !expanded

  return (
    <div className={`relative rounded-xl border border-border ${className}`}>
      <motion.button
        type="button"
        onClick={handleCopy}
        className="absolute top-4 right-4 p-2 rounded-lg bg-background/80 border border-border opacity-0 hover:opacity-100 transition-opacity z-10"
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.95 }}
      >
        {copied ? (
          <Check size={18} className="text-green-500" />
        ) : (
          <Copy size={18} className="text-foreground/70" />
        )}
      </motion.button>

      <div
        className="relative overflow-hidden rounded-xl transition-[max-height] duration-300 ease-in-out"
        style={{
          maxHeight: isCollapsed ? CODE_BLOCK_COLLAPSED_HEIGHT : undefined,
        }}
      >
        <SyntaxHighlighter
          language={language}
          style={atomOneDark}
          customStyle={{
            padding: '20px',
            margin: 0,
            fontSize: '14px',
            lineHeight: '1.5',
          }}
          wrapLines
        >
          {code}
        </SyntaxHighlighter>

        {isCollapsed && (
          <div
            className="pointer-events-none absolute inset-x-0 bottom-0 h-16 bg-gradient-to-t from-[#282c34] to-transparent"
            aria-hidden
          />
        )}
      </div>

      {collapsible && (
        <button
          type="button"
          onClick={() => setExpanded((prev) => !prev)}
          className="flex w-full items-center justify-center gap-1.5 border-t border-border bg-muted/50 px-4 py-2.5 text-sm font-medium text-foreground/80 transition-colors hover:bg-muted hover:text-foreground"
        >
          {expanded ? (
            <>
              Show less
              <ChevronUp size={16} />
            </>
          ) : (
            <>
              Show all code
              <ChevronDown size={16} />
            </>
          )}
        </button>
      )}
    </div>
  )
}

component-card.content:
'use client'

import { useRouter } from 'next/navigation'
import { motion } from 'framer-motion'
import { useState } from 'react'
import { Copy, Check } from 'lucide-react'
import type { GalleryComponent } from '@/lib/gallery/types'
import Card from './neo-brutalism/card'
import styled from 'styled-components'

interface ComponentCardProps {
  component: GalleryComponent
  preview?: React.ReactNode
}

const PreviewSlot = styled.div`
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;

  .preview-inner {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    transform: scale(0.9);
  }

  .copy-btn {
    position: absolute;
    top: 0.5rem;
    right: 0.5rem;
    padding: 0.5rem;
    border: var(--border-width) solid var(--border-color);
    border-radius: var(--border-radius);
    background: var(--color-surface);
    box-shadow: var(--shadow-md-1);
    opacity: 0;
    z-index: 20;
    cursor: pointer;
    transition: opacity 0.15s ease, transform 0.15s ease;
  }

  &:hover .copy-btn {
    opacity: 1;
  }

  .copy-btn:hover {
    transform: translate(1.5px, 1.5px);
    box-shadow: var(--shadow-md-1);
  }
`

const Meta = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;

  .tag {
    padding: 0.3rem 0.65rem;
    border: var(--border-width) solid var(--border-color);
    border-radius: var(--border-radius);
    background: var(--color-accent-4);
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--color-text-black);
  }

  .section {
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-text-black);
  }
`

export function ComponentCard({ component, preview }: ComponentCardProps) {
  const router = useRouter()
  const [copied, setCopied] = useState(false)

  const componentKey = component.sectionId
    ? `${component.sectionId}/${component.slug}`
    : component.slug
  const installCommand = `npx @explorers_111/byteui add ${componentKey}`

  const handleCopy = () => {
    navigator.clipboard.writeText(installCommand)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  const href = `/component/${component.sectionId}/${component.slug}`

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: '-100px' }}
      transition={{ duration: 0.5 }}
      className="h-full"
    >
      <Card
        fluid
        title={component.name}
        description={component.description}
        onClick={(e) => {
          const target = e.target as HTMLElement
          if (target.closest('a') || target.closest('button')) {
            return
          }
          router.push(href)
        }}
        footer={
          <Meta>
            {component.tags.slice(0, 2).map((tag) => (
              <span key={tag} className="tag">
                {tag}
              </span>
            ))}
            <span className="section">{component.sectionTitle}</span>
          </Meta>
        }
      >
        <PreviewSlot>
          {preview && <div className="preview-inner">{preview}</div>}
          <button
            type="button"
            className="copy-btn"
            onClick={(e) => {
              e.preventDefault()
              e.stopPropagation()
              handleCopy()
            }}
            aria-label="Copy install command"
          >
            {copied ? (
              <Check size={18} className="text-green-600" />
            ) : (
              <Copy size={18} />
            )}
          </button>
        </PreviewSlot>
      </Card>
    </motion.div>
  )
}

