navbar.content:
'use client'

import Link from 'next/link'
import Image from 'next/image'
import { Moon, Sun } from 'lucide-react'
import { useTheme } from 'next-themes'
import { useEffect, useState } from 'react'
import { motion } from 'framer-motion'
import styled from 'styled-components'
import NeoThemeWrapper from './neo-brutalism/neo.theme'

const NavbarWrapper = styled.div`
  position: relative;
  top: 0;
  z-index: 50;
  width: 100%;
  max-width: 60rem;
  rotate: -2deg;
  margin: 0 auto;
  margin-top: 2rem;
  padding: 1.5rem 1rem 0.5rem 1rem;
`

const StyledNavbar = styled.nav`
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--color-accent-2);
  border: var(--border-width) solid var(--border-color);
  border-radius: var(--border-radius);
  padding: 0.75rem 1.25rem;
  box-shadow: var(--shadow-lg-1);
  transition: all 0.2s ease-in-out;
`

const LogoContainer = styled(Link)`
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-shrink: 0;
  text-decoration: none;

  .logo-badge {
    background-color: var(--color-bg);
    border-radius: 9999px;
    display: flex;
    scale: 1.2;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    transition: transform 0.2s ease;
  }

  &:hover .logo-badge {
    transform: scale(1.2);
  }

  .logo-title {
    font-family: 'Mash', sans-serif;
    font-weight: 800;
    font-size: 1.4rem;
    letter-spacing: -0.025em;
    color: var(--color-text-black);
    gap: 2;
  }
`

const NavLinks = styled.div`
  display: flex;
  align-items: center;
  gap: 5rem;
  flex: 1;
  justify-content: center;


  @media (min-width: 768px) {
    gap: 6rem;

  }
`

const NavLinkItem = styled(Link)`
  font-size: 1.4rem;
  font-weight: 700;
  line-height: 1.25rem;
  color: var(--color-text-black);
  text-decoration: none;
  transition: opacity 0.2s ease;

  &:hover {
    opacity: 0.7;
  }

`

const ThemeButton = styled(motion.button)`
  background-color: var(--color-bg);
  height: 2.5rem;
  min-width: 2.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-weight: 700;
  border: var(--border-width) solid var(--border-color);
  box-shadow: var(--shadow-md-1);
  cursor: pointer;
  transition: all 0.15s ease;
  border-radius: var(--border-radius);

  &:hover {
    opacity: 0.9;
  }

  &:active {
    transform: translate(2px, 2px);
    box-shadow: none;
  }
`

export function Navbar() {
  const { theme, setTheme } = useTheme()
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
  }, [])

  const navItems = [
    { label: 'Gallery', href: '/gallery' },
    { label: 'Categories', href: '/categories' },
    { label: 'Docs', href: '/docs' },
  ]

  return (<NeoThemeWrapper>
    <NavbarWrapper>
      <StyledNavbar>
        {/* Logo */}
        <LogoContainer href="/">
          <div className="logo-badge">
            <Image
              src="/android-chrome-192x192.png"
              alt="ByteUI Logo"
              width={24}
              height={24}
              className="rounded-full"
            />
          </div>
          <span className="logo-title">ByteUI</span>
        </LogoContainer>

        {/* Nav Items */}
        <NavLinks>
          {navItems.map((item) => (
            <NavLinkItem key={item.href} href={item.href}>
              {item.label}
            </NavLinkItem>
          ))}
        </NavLinks>

        {/* Theme Toggle */}
        {mounted && (
          <ThemeButton
            onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
            whileTap={{ scale: 0.95 }}
            aria-label="Toggle Theme"
          >
            {theme === 'dark' ? (
              <Sun size={20} className="text-yellow-400" />
            ) : (
              <Moon size={20} className="text-black" />
            )}
          </ThemeButton>
        )}
      </StyledNavbar>
    </NavbarWrapper>
    </NeoThemeWrapper>
  )
}

neo-brutalism/_combobox.content:
'use client'
import React, { FC, useState, useRef, useEffect } from 'react';
import styled from 'styled-components';
import NeoThemeWrapper from './neo.theme';
import { ArrowBigDownDash } from 'lucide-react';

const StyledWrapper = styled.div`
  position: relative;
  width: 100%;
  max-width: 360px;
  min-width: 240px;

  .combo-box {
    width: 100%;
    padding: 14px 16px;
    border: var(--border-width) solid var(--border-color);
    border-radius: var(--border-radius);
    background: var(--color-accent-2);
    color: var(--color-text-black);
    font-size: 16px;
    cursor: pointer;
    box-shadow: var(--shadow-md-1);
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: 52px;
    font-weight: 700;
    font-family: var(--font-lexend);
  }

  .combo-box:hover {
    box-shadow: 1.5px 1.5px 0 var(--shadow-md-1);
    transform: translate(1.5px, 1.5px);
  }

  .arrow {
    transition: transform 0.3s ease;
  }

  .combo-box.open .arrow {
    transform: rotate(180deg);
  }

  .dropdown {
    position: absolute;
    top: calc(100% + 8px);
    left: 0;
    width: 100%;
    background: var(--color-bg);
    border: var(--border-width) solid var(--border-color);
    border-radius: var(--border-radius);
    box-shadow: var(--shadow-lg);
    max-height: 360px;
    overflow-y: auto;
    z-index: 100;
    display: none;
  }

  .combo-box.open + .dropdown {
    display: block;
  }

  .search-input {
    width: 100%;
    padding: 14px 16px;
    border: none;
    border-bottom: var(--border-width) solid var(--color-text);
    background: var(--color-bg);
    color: var(--color-text);
    font-size: 15px;
    position: sticky;
    top: 0;
  }

  .option {
    padding: 13px 16px;
    cursor: pointer;
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    gap: 12px;
    user-select: none;
  }

  .option:hover,
  .option.selected {
    background: var(--color-accent-2);
    color: var(--color-text-black);
    box-shadow: var(--shadow-md-2);
    border-radius: var(--border-radius);
  }

  .option.selected {
    font-weight: 700;
  }

  .no-results {
    padding: 20px;
    text-align: center;
    color: var(--color-text-muted);
    font-family: var(--font-lexend);
  }
`;

export interface Option {
  value: string;
  label: string;
  icon?: React.ReactNode;
}

interface ComboBoxProps {
  options?: Option[];           
  value?: string;
  onChange?: (value: string) => void;
  placeholder?: string;
  className?: string;
  searchPlaceholder?: string;
  [key: string]: unknown;
}

const ComboBox: FC<ComboBoxProps> = ({
  options = [],                    
  value: controlledValue,
  onChange,
  placeholder = 'Select an option',
  className = '',
  searchPlaceholder = 'Search...',
  ...props
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const containerRef = useRef<HTMLDivElement>(null);
  const [internalValue, setInternalValue] = useState(controlledValue || '');

  useEffect(() => {
    if (controlledValue !== undefined) {
      setInternalValue(controlledValue);
    }
  }, [controlledValue]);

  const value = controlledValue !== undefined ? controlledValue : internalValue;

  // Safe find
  const selectedOption = options.find(opt => opt.value === value);

  const filteredOptions = options.filter(option =>
    option.label.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelect = (optionValue: string) => {
    if (controlledValue === undefined) {
      setInternalValue(optionValue);
    }
    onChange?.(optionValue);
    setSearchTerm('');
    setIsOpen(false);
  };

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
        setSearchTerm('');
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <StyledWrapper ref={containerRef}>
      <NeoThemeWrapper>
        <div className={className} {...props}>
          <div
            className={`combo-box ${isOpen ? 'open' : ''}`}
            onClick={() => setIsOpen(!isOpen)}
          >
            {selectedOption ? (
              <div style={{ display: 'flex', alignItems: 'center' }}>
                {selectedOption.icon}
                {selectedOption.label}
              </div>
            ) : (
              <span style={{ color: '#000000ff' }}>{placeholder}</span>
            )}
            <ArrowBigDownDash className="arrow" />
          </div>

          <div className="dropdown">
            <input
              type="text"
              className="search-input"
              placeholder={searchPlaceholder}
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              autoFocus
            />

            {filteredOptions.length > 0 ? (
              filteredOptions.map((option) => (
                <div
                  key={option.value}
                  className={`option ${value === option.value ? 'selected' : ''}`}
                  onClick={() => handleSelect(option.value)}
                >
                  {option.icon}
                  {option.label}
                </div>
              ))
            ) : (
              <div className="no-results">
                {searchTerm ? 'No matching results found' : 'No options available'}
              </div>
            )}
          </div>
        </div>
      </NeoThemeWrapper>
