        color: var(--color-text-black);
        font-family: var(--font-sans);
        max-width: 600px;
        border-radius: var(--border-radius);
    }
        .dialog h2 {
            margin: 0 0 10px;
            font-size: 2rem;
            font-weight: bold;
        }
            .dialog p {
                margin: 0;
                font-size: 1.2rem;
            }
