import NeoThemeWrapper from './neo.theme';

type CardVariant = 'simple' | 'image' | 'text';


interface CardProps {
  className?: string;
  children?: React.ReactNode;
  variant?: CardVariant;
  /** @deprecated use `variant` */
  varient?: CardVariant;
  footer?: React.ReactNode;
  title?: string;
  description?: string;
  image?: string;
  imageURL?: string;
  fluid?: boolean;
  onClick?: (e: React.MouseEvent<HTMLDivElement>) => void;
}

