  @keyframes bounce2 {
    0%,
    100% {
      translate: 0px 46px;
    }
    50% {
      translate: 0px 58px;
    }
  }
    @keyframes bounce3 {
    0%,
    100% {
      translate: 0px 56px;
    }
    50% {
      translate: 0px 66px;
    }
  }
    @keyframes bounce4 {
    0%,
    100% {
      translate: 0px 66px;
    }
    50% {
      translate: 0px 76px;
    }
  }
    @keyframes bounce5 {
    0%,
    100% {
      translate: 0px 36px;
    }
    50% {
      translate: 0px 26px;
    }
  }
  #bounce {
    animation: bounce 4s ease-in-out infinite;
  }
  #bounce2 {
    animation: bounce2 4s ease-in-out infinite;
    animation-delay: 0.5s;
  }
  #bounce3 {
    animation: bounce3 4s ease-in-out infinite;
    animation-delay: 1s;
  }
  #bounce4 {
    animation: bounce4 4s ease-in-out infinite;
    animation-delay: 1.5s;
  }
  #bounce5 {
    animation: bounce5 4s ease-in-out infinite;
    animation-delay: 0.6s;
  }`

export default Loader;

