            </TriggerBlock>

            <TriggerBlock $color="var(--error)">
              <Button variant="primary" onClick={showDestructiveToast} style={{ width: '100%' }}>
                Trigger Alert
              </Button>
            </TriggerBlock>
          </ShowcaseGrid>
        </ControlCard>
      </PageContainer>
