};

export default ToolTip;

const StyledWrapper = styled.div`
  display: inline-flex;
  align-items: center;
  gap: 12px;
  position: relative;

  .badge-container {
    position: relative;
    display: inline-block;
  }

  .tooltip-text {
    visibility: hidden;
    position: absolute;
    bottom: calc(100% + 14px);
    left: 50%;
    transform: translateX(-50%) translateY(8px);
    background-color: var(--color-accent-4);
